/*
 * Runtime image filesystem (LibOS/runtime split).
 *
 * The runtime files (python, glibc, native libraries, application data) used
 * to be xxd-baked into libsysdb.so as pseudo "str" nodes (fs/static/fs.c,
 * generated by tools/fn/filesystem/fs.py). They now come as one page-aligned
 * image (tools/fn/filesystem/mkimage.py) that the guest loads into the
 * monitor's runtime store once and the monitor maps read-only into every
 * zygote that names it. The PAL reports where (pal_public_state.runtime_images,
 * filled from the monitor's RuntimeInfo process call); this file walks the
 * image's table of contents and registers the same pseudo nodes the bake did,
 * pointing at the mapped bytes. Top-level directories become pseudo roots, so
 * the manifests keep mounting them by name:
 *   { type = "pseudo", path = "/lib", uri = "lib" }
 *
 * Image layout (little-endian, page = 4096), see mkimage.py:
 *   page 0  header { magic "WALLETRT", u32 version, u32 hdr_size, u64 toc_off,
 *                    toc_count, strtab_off, strtab_size, data_off, total_size }
 *   toc     toc_count entries { u32 type, mode, parent, name_off; u64 data_off, size }
 *           in pre-order (a parent precedes its children)
 *   strtab  NUL-terminated names and symlink targets
 *   data    every file at a 4 KiB-aligned data_off, zero-padded
 */

#include "api.h"
#include "libos_flags_conv.h"
#include "libos_fs.h"
#include "libos_fs_pseudo.h"
#include "libos_internal.h"
#include "pal.h"
#include "pal_error.h"

#define IMG_MAGIC     "WALLETRT"
#define IMG_VERSION   1
#define IMG_PAGE      4096
#define IMG_NO_PARENT 0xFFFFFFFFu

enum { IMG_DIR = 1, IMG_FILE = 2, IMG_LINK = 3 };

struct img_header {
    char magic[8];
    uint32_t version;
    uint32_t hdr_size;
    uint64_t toc_off;
    uint64_t toc_count;
    uint64_t strtab_off;
    uint64_t strtab_size;
    uint64_t data_off;
    uint64_t total_size;
} __attribute__((packed));

struct img_entry {
    uint32_t type;
    uint32_t mode;
    uint32_t parent;
    uint32_t name_off;
    uint64_t data_off;
    uint64_t size;
} __attribute__((packed));

/* Names that are pseudo roots of the LibOS itself; an image must not merge into them. */
static const char* const g_reserved_roots[] = { "proc", "dev", "sys", "etc" };

static int init_one_image(const char* base, size_t size, size_t idx) {
    if (size < IMG_PAGE) {
        log_error("runtime image %zu: too small (%zu bytes)", idx, size);
        return -EINVAL;
    }
    const struct img_header* h = (const struct img_header*)base;
    if (memcmp(h->magic, IMG_MAGIC, sizeof(h->magic)) != 0 || h->version != IMG_VERSION ||
            h->hdr_size != sizeof(*h)) {
        log_error("runtime image %zu: bad header (version %u)", idx, h->version);
        return -EINVAL;
    }
    if (h->total_size != size || h->toc_count > PSEUDO_MAX_NODES ||
            h->toc_off < sizeof(*h) ||
            h->toc_off + h->toc_count * sizeof(struct img_entry) > h->strtab_off ||
            h->strtab_off + h->strtab_size > h->data_off || h->data_off > size ||
            h->strtab_size == 0 || base[h->strtab_off + h->strtab_size - 1] != '\0') {
        log_error("runtime image %zu: header offsets out of range", idx);
        return -EINVAL;
    }

    const struct img_entry* toc = (const struct img_entry*)(base + h->toc_off);
    const char* strtab = base + h->strtab_off;

    struct pseudo_node** nodes = calloc(h->toc_count, sizeof(*nodes));
    if (!nodes)
        return -ENOMEM;

    int ret = 0;
    size_t files = 0;
    for (uint64_t i = 0; i < h->toc_count; i++) {
        const struct img_entry* e = &toc[i];
        if (e->name_off >= h->strtab_size) {
            ret = -EINVAL;
            goto out;
        }
        const char* name = strtab + e->name_off;
        if (!*name || strchr(name, '/')) {
            ret = -EINVAL;
            goto out;
        }

        struct pseudo_node* parent = NULL;
        if (e->parent != IMG_NO_PARENT) {
            if (e->parent >= i || !nodes[e->parent] || nodes[e->parent]->type != PSEUDO_DIR) {
                ret = -EINVAL;
                goto out;
            }
            parent = nodes[e->parent];
        }

        struct pseudo_node* node;
        switch (e->type) {
            case IMG_DIR:
                if (!parent) {
                    for (size_t r = 0; r < ARRAY_SIZE(g_reserved_roots); r++) {
                        if (!strcmp(name, g_reserved_roots[r])) {
                            log_error("runtime image %zu: top-level '%s' is reserved", idx, name);
                            ret = -EINVAL;
                            goto out;
                        }
                    }
                    /* A root of that name already exists (another image, or a baked tree):
                     * reuse it - directory-level merge. */
                    node = pseudo_find_root(name);
                    if (!node)
                        node = pseudo_add_root_dir(name);
                } else {
                    node = pseudo_add_dir(parent, name);
                }
                node->perm = e->mode & PERM_r_xr_xr_x;
                break;

            case IMG_FILE:
                if (!parent || e->data_off % IMG_PAGE || e->data_off < h->data_off ||
                        e->data_off + e->size < e->data_off || e->data_off + e->size > size) {
                    ret = -EINVAL;
                    goto out;
                }
                node = pseudo_add_str(parent, name, /*load=*/NULL);
                node->str.no_free     = true;
                node->str.static_data = base + e->data_off;
                node->str.static_size = e->size;
                node->str.image_off   = e->data_off;
                /* Never writable: the bytes are the monitor's shared mapping. */
                node->perm = e->mode & PERM_r_xr_xr_x;
                files++;
                break;

            case IMG_LINK:
                if (!parent || e->data_off >= h->strtab_size) {
                    ret = -EINVAL;
                    goto out;
                }
                node = pseudo_add_link(parent, name, /*follow_link=*/NULL);
                node->link.target = strtab + e->data_off;
                break;

            default:
                ret = -EINVAL;
                goto out;
        }
        nodes[i] = node;
    }
    log_debug("runtime image %zu: %lu nodes (%zu files), %lu bytes at %p", idx,
              (unsigned long)h->toc_count, files, (unsigned long)size, base);

out:
    if (ret < 0)
        log_error("runtime image %zu: malformed table of contents", idx);
    free(nodes);
    return ret;
}

/*
 * Zero-copy mapping of an image file (phase E of the split). A mapping without
 * PROT_WRITE aliases the image's own pages (PalRuntimeImageMap: on svsm the
 * monitor maps the runtime store's physical pages read-only into the process),
 * so libraries and the interpreter are not copied into every zygote. The part
 * of the request past the file's last page is anonymous zero memory (Linux
 * would SIGBUS there; ld.so maps such tails and never touches them). Writable
 * requests (.data, bss) need a private copy: -ENOSYS, the caller falls back to
 * generic_emulated_mmap. A later mprotect to writable is handled by the host
 * (the page is copied first).
 */
int image_file_mmap(struct pseudo_node* node, void* addr, size_t size, int prot, int flags,
                    uint64_t offset) {
    if (prot & PROT_WRITE)
        return -ENOSYS;
    size_t file_pages = ALLOC_ALIGN_UP(node->str.static_size);
    if (offset >= file_pages)
        return -ENOSYS;   /* nothing of the file in range: zero pages, generic path */
    size_t in_file = MIN(size, file_pages - offset);
    pal_prot_flags_t pal_prot = LINUX_PROT_TO_PAL(prot, flags);
    /* MAP_PRIVATE adds PAL_PROT_WRITECOPY, which asks the host for a private
     * copy; the alias is read-only and a later mprotect to writable copies. */
    pal_prot_flags_t alias_prot = pal_prot & ~PAL_PROT_WRITECOPY;
    int ret = PalRuntimeImageMap(addr, in_file, alias_prot, node->str.image_off + offset);
    if (ret < 0) {
        log_debug("image mmap of %s at %p (%lu bytes) refused: %s - copying", node->name, addr,
                  (unsigned long)in_file, pal_strerror(ret));
        return -ENOSYS;
    }
    if (in_file < size) {
        ret = PalVirtualMemoryAlloc((char*)addr + in_file, size - in_file, pal_prot);
        if (ret < 0) {
            PalVirtualMemoryFree(addr, in_file);
            return pal_to_unix_errno(ret);
        }
    }
    return 0;
}

int init_image_fs(void) {
    for (size_t i = 0; i < PAL_MAX_RUNTIME_IMAGES; i++) {
        const struct pal_runtime_image* img = &g_pal_public_state->runtime_images[i];
        if (!img->size)
            break;
        int ret = init_one_image(img->base, img->size, i);
        if (ret < 0)
            return ret;
    }
    return 0;
}
